"""Held-out injury-phrasing sets — `SUCCESS-METRICS.md` §2's OBSERVED recall metric.

Two sets, deliberately kept as separate files and reported as separate numbers:

* **weak** (`injury_phrasings_weak.yaml`, criterion 3) — not in the golden set and not used to build the
  lexicon, but written by the lexicon's own author. Closer to a self-assessment than a test.
* **independent** (`injury_phrasings_independent.yaml`, criterion 14, Stage 6) — generated by an isolated
  agent that never read `agents/lexicon.py` or `INTENT-TAXONOMY.md` §2.4. Marco's addition at Phase 6
  approval, on the grounds that the softest number in the phase was the one attached to the safety gate.

**Never blended into a single recall figure.** The gap between them is the informative quantity: if the
weak set scores far higher, the difference is the size of the author's blind spot, and averaging the two
would conceal exactly that. Loading them through one function with a required `kind` argument, rather than
a `load_holdout()` that silently concatenates, is the mechanism for that — you cannot merge them by
accident.

Neither set may be used to tune the detector. A held-out set used for tuning is no longer held out, and
patching `agents/lexicon.py` to catch what it missed converts the one honest number in the phase back into
a self-assessment.

A third set was added in Phase 7 and is a different kind of thing:

* **tuning** (`../tuning/injury_phrasings_tuning.yaml`, `BUILD-PLAN.md` §2.1) — generated by an isolated
  agent on the same protocol, and **expected** to be contaminated by tuning. That is what it is for. It
  exists so the ablation ladder has somewhere to iterate that is not the verification set.

Its isolation requirement is narrower than the independent set's, and the difference is worth stating
because it looks like an inconsistency: the tuning set's author was told *which shapes the detector gets
wrong* (vehicle damage in human terms, ordinary claim openings, right-scoped negation), since tuning against
known failure classes is the whole activity. What it was **not** allowed to see is the independent set's
*items* or the detector's *implementation* — because phrasings copied from the verification set would make
tuning against this file a way of tuning against that one.

**Model-based measurement against the independent set is guarded** by `holdout_ledger`: reading it and
constructing a real Bedrock client in the same process requires a declared `verification_run(...)`, which
appends to the ledger. Reading it alone is free, so the already-spent deterministic L1 number stays in the
regression baseline. See that module for why the guard and the ledger are the same object.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path

import yaml

from evals.holdout_ledger import note_independent_set_read
from fnol_voice_agent.models.enums import KabcoCode

HOLDOUT_DIR = Path(__file__).resolve().parent / "holdout"
TUNING_DIR = Path(__file__).resolve().parent / "tuning"


class HoldoutKind(StrEnum):
    WEAK = "weak"
    INDEPENDENT = "independent"
    TUNING = "tuning"


_FILENAMES = {
    HoldoutKind.WEAK: "injury_phrasings_weak.yaml",
    HoldoutKind.INDEPENDENT: "injury_phrasings_independent.yaml",
    HoldoutKind.TUNING: "injury_phrasings_tuning.yaml",
}

_DIRECTORIES = {
    HoldoutKind.WEAK: HOLDOUT_DIR,
    HoldoutKind.INDEPENDENT: HOLDOUT_DIR,
    HoldoutKind.TUNING: TUNING_DIR,
}


@dataclass(frozen=True)
class InjuryPhrasing:
    text: str
    kabco: KabcoCode
    should_escalate: bool
    kind: HoldoutKind


class HoldoutSetMissingError(FileNotFoundError):
    """The requested set has not been generated yet."""


class HoldoutStructure:
    """Aggregate facts about a set, without handing back its items.

    The guard on the independent set exists to stop the detector being changed in response to what
    that set showed. A structural test -- does it parse, does it have both polarities, is it weighted
    toward indirect phrasing -- needs none of the phrasings themselves, only counts over them. So
    `structural_summary` is unguarded and `load_holdout` is not: **the lock is on the items, not on
    facts about the file.**

    This is a discipline mechanism, not a sandbox. The texts are reachable by anyone who wants them
    badly enough. What it removes is the accident: a test that prints a failing item into a terminal,
    or a summary that grows an "examples" field one convenience at a time.
    """

    def __init__(self, kind: HoldoutKind, phrasings: list[InjuryPhrasing]) -> None:
        self.kind = kind
        self.total = len(phrasings)
        self.positives = sum(1 for p in phrasings if p.should_escalate)
        self.negatives = self.total - self.positives
        self.kabco_counts: dict[str, int] = {}
        for p in phrasings:
            self.kabco_counts[p.kabco.value] = self.kabco_counts.get(p.kabco.value, 0) + 1
        self._phrasings = phrasings

    def count(
        self,
        *,
        should_escalate: bool | None = None,
        kabco: KabcoCode | None = None,
        containing: str | None = None,
    ) -> int:
        """Counts items matching every supplied filter. Returns a number, never a text."""
        matches = self._phrasings
        if should_escalate is not None:
            matches = [p for p in matches if p.should_escalate is should_escalate]
        if kabco is not None:
            matches = [p for p in matches if p.kabco is kabco]
        if containing is not None:
            needle = containing.lower()
            matches = [p for p in matches if needle in p.text.lower()]
        return len(matches)

    def duplicate_text_count(self) -> int:
        return self.total - len({p.text.strip().lower() for p in self._phrasings})


def structural_summary(kind: HoldoutKind, *, directory: Path | None = None) -> HoldoutStructure:
    """Unguarded, deliberately -- see `HoldoutStructure`."""
    return HoldoutStructure(kind, _read_phrasings(kind, directory))


def _read_phrasings(kind: HoldoutKind, directory: Path | None) -> list[InjuryPhrasing]:
    path = (directory or _DIRECTORIES[kind]) / _FILENAMES[kind]
    if not path.exists():
        raise HoldoutSetMissingError(
            f"{path} does not exist. These sets are generated by isolated agents that have not read "
            f"agents/lexicon.py -- they are deliberately not authored inline here."
        )
    raw = yaml.safe_load(path.read_text())
    entries = raw["phrasings"]
    parsed = [
        InjuryPhrasing(
            text=e["text"],
            kabco=KabcoCode(e["kabco"]),
            should_escalate=bool(e["should_escalate"]),
            kind=kind,
        )
        for e in entries
    ]
    if not any(p.should_escalate for p in parsed):
        raise ValueError(f"{path}: no positive cases -- recall would be undefined")
    if all(p.should_escalate for p in parsed):
        raise ValueError(
            f"{path}: every case is a positive, so a detector that escalates on everything scores "
            f"100%. A held-out set without negatives measures nothing about false escalation."
        )
    return parsed


def load_holdout(kind: HoldoutKind, *, directory: Path | None = None) -> list[InjuryPhrasing]:
    """Reading the independent set is permitted and free. What is guarded is reading it *and*
    calling a model in the same process -- see `holdout_ledger`. A deterministic L1 pass is
    therefore unaffected, which is why `make eval` still reports (and still gates on) the L1
    number this set has already been spent on."""
    if kind is HoldoutKind.INDEPENDENT:
        note_independent_set_read()
    return _read_phrasings(kind, directory)
